1	import type { NextRequest } from 'next/server'
2	import { NextResponse } from 'next/server'
3	import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
4	import { authedRatelimit } from '@/lib/rate-limit'
5	import { logger } from '@/lib/logger'
6	
7	const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp']
8	const MAX_BYTES = 5 * 1024 * 1024 // 5 MB — matches bucket file_size_limit
9	const SIGNED_URL_SECONDS = 60 * 60 * 24 * 365 // 1 year
10	
11	export async function POST(request: NextRequest) {
12	  const authUser = await getAuthenticatedUser()
13	  if (!authUser) {
14	    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
15	  }
16	
17	  const { success } = await authedRatelimit.limit(authUser.user.id)
18	  if (!success) {
19	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
20	  }
21	
22	  let formData: FormData
23	  try {
24	    formData = await request.formData()
25	  } catch {
26	    return NextResponse.json({ error: 'Invalid form data' }, { status: 400 })
27	  }
28	
29	  const file = formData.get('file')
30	  const clientId = formData.get('client_id')
31	
32	  if (!(file instanceof File)) {
33	    return NextResponse.json({ error: 'No file provided' }, { status: 400 })
34	  }
35	  if (typeof clientId !== 'string' || clientId.length === 0) {
36	    return NextResponse.json({ error: 'client_id required' }, { status: 400 })
37	  }
38	
39	  if (!ALLOWED_MIME_TYPES.includes(file.type)) {
40	    return NextResponse.json(
41	      { error: `File type not allowed. Use: ${ALLOWED_MIME_TYPES.join(', ')}` },
42	      { status: 400 }
43	    )
44	  }
45	  if (file.size > MAX_BYTES) {
46	    return NextResponse.json(
47	      { error: `File must be under 5 MB. Yours is ${(file.size / 1024 / 1024).toFixed(1)} MB.` },
48	      { status: 400 }
49	    )
50	  }
51	
52	  try {
53	    const supabase = await createClient()
54	
55	    // Verify the client belongs to the caller's studio.
56	    const { data: client, error: ownsErr } = await supabase
57	      .from('clients')
58	      .select('id')
59	      .eq('id', clientId)
60	      .eq('studio_id', authUser.studioId)
61	      .single()
62	    if (ownsErr || !client) {
63	      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
64	    }
65	
66	    const ext = file.type.split('/')[1] ?? 'jpg'
67	    const path = `${authUser.studioId}/${clientId}/avatar.${ext}`
68	
69	    const { error: uploadError } = await supabase.storage
70	      .from('client-avatars')
71	      .upload(path, file, {
72	        contentType: file.type,
73	        upsert: true,
74	      })
75	
76	    if (uploadError) {
77	      logger.error({ err: uploadError, studioId: authUser.studioId, clientId }, 'client avatar upload failed')
78	      return NextResponse.json({ error: 'Upload failed' }, { status: 500 })
79	    }
80	
81	    const { data: signed, error: signErr } = await supabase.storage
82	      .from('client-avatars')
83	      .createSignedUrl(path, SIGNED_URL_SECONDS)
84	    if (signErr || !signed?.signedUrl) {
85	      logger.error({ err: signErr, clientId }, 'client avatar sign failed')
86	      return NextResponse.json({ error: 'Upload succeeded but signing failed' }, { status: 500 })
87	    }
88	
89	    return NextResponse.json({ url: signed.signedUrl, path })
90	  } catch (err) {
91	    logger.error({ err, studioId: authUser.studioId }, 'client avatar upload unexpected error')
92	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
93	  }
94	}
