34	
35	interface ClientsPageClientProps {
36	  initialClients: Client[]
37	  tagLibrary: ClientTag[]
38	}
39	
40	const DEFAULT_FILTERS: ClientFilters = {
41	  q: '',
42	  tags: [],
43	  vip: false,
44	  inactive: false,
45	  noShows: false,
46	  showArchived: false,
47	  hasAlerts: false,
48	  spendingTier: '',
49	  artistIds: [],
50	  serviceIds: [],
51	  lastVisitRange: '',
