54	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
55	  const router = useRouter()
56	  const searchParams = useSearchParams()
57	
58	  const [clients, setClients] = useState<Client[]>(initialClients)
59	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
60	  const [selectedIds, setSelectedIds] = useState<string[]>([])
61	  const [loading, setLoading] = useState(false)
62	  const [fetchError, setFetchError] = useState<Error | null>(null)
63	  const [drawerOpen, setDrawerOpen] = useState(false)
64	  const [editingClient, setEditingClient] = useState<Client | null>(null)
65	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
66	  const [page, setPage] = useState(1)
67	  const [hasMore, setHasMore] = useState(false)
68	  const [totalCount, setTotalCount] = useState<number | null>(null)
69	
70	  // Saved views
71	  const [views, setViews] = useState<ClientView[]>([])
72	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
73	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
74	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
75	  const [editingView, setEditingView] = useState<ClientView | null>(null)
76	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
77	
78	  const fetchViews = useCallback(async () => {
79	    try {
80	      const res = await fetch('/api/client-views')
81	      if (res.ok) {
82	        const json = await res.json() as { data: ClientView[] }
83	        setViews(json.data ?? [])
84	        // Auto-activate first system default view
85	        const defaultView = json.data?.find((v) => v.is_default)
86	        if (defaultView) {
87	          setActiveViewId((prev) => prev ?? defaultView.id)
88	        }
89	      }
90	    } catch {
91	      toast.error('Failed to load views', { description: 'Using All clients as default' })
92	    }
93	  }, [])
94	
95	  // Load saved views on mount
96	  useEffect(() => {
97	    void fetchViews()
98	  }, [fetchViews])
99	
100	  // Restore page from URL
101	  useEffect(() => {
102	    const p = parseInt(searchParams.get('page') ?? '1', 10)
103	    if (p > 1) {
104	      setPage(p)
105	    }
106	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
107	
108	  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
109	    setLoading(true)
110	    setFetchError(null)
111	    try {
112	      const params = new URLSearchParams()
113	      if (f.q) params.set('q', f.q)
114	      if (f.tags.length) params.set('tags', f.tags.join(','))
115	      if (f.vip) params.set('vip', 'true')
116	      if (f.inactive) params.set('inactive', 'true')
117	      if (f.noShows) params.set('no_show', 'true')
118	      if (!f.showArchived) params.set('archived', 'false')
119	      else params.set('archived', 'any')
120	      if (f.spendingTier) params.set('spending', f.spendingTier)
121	      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
122	      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
123	      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
124	      params.set('page', String(p))
125	      params.set('per_page', '50')
126	
127	      const res = await fetch(`/api/clients?${params.toString()}`)
128	      if (!res.ok) throw new Error('Failed to load clients')
129	      const json = await res.json() as { data: Client[]; count: number }
130	
131	      if (p === 1) {
132	        setClients(json.data ?? [])
133	      } else {
134	        setClients((prev) => [...prev, ...(json.data ?? [])])
135	      }
136	      setTotalCount(json.count ?? null)
137	      setHasMore((json.data?.length ?? 0) >= 50)
138	    } catch (err) {
139	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
140	    } finally {
141	      setLoading(false)
142	    }
143	  }, [])
144	
145	  useEffect(() => {
146	    void fetchClients(filters, 1)
147	    setPage(1)
148	    setSelectedIds([])
149	  }, [filters, fetchClients])
150	
151	  function handleFiltersChange(f: ClientFilters) {
152	    setFilters(f)
153	    setHasUnsavedChanges(true)
154	  }
155	
156	  function handleViewChange(viewId: string | null) {
157	    setActiveViewId(viewId)
158	    setHasUnsavedChanges(false)
159	    const view = views.find((v) => v.id === viewId)
160	    if (view) {
161	      // Apply view filters
162	      const viewFilters = view.filters as Partial<ClientFilters>
163	      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
164	    } else {
165	      setFilters(DEFAULT_FILTERS)
166	    }
167	  }
168	
169	  async function handleDeleteView(viewId: string) {
170	    try {
171	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
172	      if (!res.ok) throw new Error('Failed to delete view')
173	      setViews((prev) => prev.filter((v) => v.id !== viewId))
174	      if (activeViewId === viewId) {
175	        const defaultView = views.find((v) => v.is_default)
176	        setActiveViewId(defaultView?.id ?? null)
177	      }
178	      toast.success('View deleted')
179	    } catch {
180	      toast.error('Failed to delete view')
181	    }
182	  }
183	
184	  async function handleDuplicateView(view: ClientView) {
185	    try {
186	      const res = await fetch('/api/client-views', {
187	        method: 'POST',
188	        headers: { 'Content-Type': 'application/json' },
189	        body: JSON.stringify({
190	          name: `${view.name} (copy)`,
191	          filters: view.filters,
192	          scope: 'private',
193	        }),
194	      })
195	      if (!res.ok) throw new Error('Failed to duplicate view')
196	      const json = await res.json() as { data: ClientView }
197	      setViews((prev) => [...prev, json.data])
198	      toast.success('View duplicated')
199	    } catch {
200	      toast.error('Failed to duplicate view')
201	    }
202	  }
203	
204	  async function handleSetDefaultView(view: ClientView) {
205	    try {
206	      const res = await fetch(`/api/client-views/${view.id}`, {
207	        method: 'PATCH',
208	        headers: { 'Content-Type': 'application/json' },
209	        body: JSON.stringify({ is_default: true }),
210	      })
211	      if (!res.ok) throw new Error('Failed to set default')
212	      // Optimistically update local state so the star + dropdown sync instantly.
213	      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
214	      toast.success(`"${view.name}" is now your default view`)
215	    } catch {
216	      toast.error('Failed to set default view')
217	    }
218	  }
219	
220	  function handleViewSaved(savedView: ClientView) {
221	    setViews((prev) => {
222	      const idx = prev.findIndex((v) => v.id === savedView.id)
223	      if (idx >= 0) {
224	        const next = [...prev]
225	        next[idx] = savedView
226	        return next
227	      }
228	      return [...prev, savedView]
229	    })
230	    setActiveViewId(savedView.id)
231	    setHasUnsavedChanges(false)
232	  }
233	
234	  function handleLoadMore() {
235	    const nextPage = page + 1
236	    setPage(nextPage)
237	    router.replace(`?page=${nextPage}`, { scroll: false })
238	    void fetchClients(filters, nextPage)
239	  }
240	
241	  function handleEditClient(client: Client) {
242	    setEditingClient(client)
243	    setDrawerOpen(true)
244	  }
245	
246	  function handleNewClient() {
247	    setEditingClient(null)
248	    setDrawerOpen(true)
249	  }
250	
251	  function handleDrawerSuccess(client: Client) {
252	    setClients((prev) => {
253	      const idx = prev.findIndex((c) => c.id === client.id)
254	      if (idx >= 0) {
255	        const next = [...prev]
256	        next[idx] = client
257	        return next
258	      }
259	      return [client, ...prev]
260	    })
261	  }
262	
263	  const hasActiveFilters = !!(
264	    filters.q || filters.tags.length > 0 || filters.vip ||
265	    filters.inactive || filters.noShows || filters.spendingTier ||
266	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
267	  )
268	
269	  const inactiveCount = useMemo(() => {
270	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
271	    return clients.filter(
272	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
273	    ).length
274	  }, [clients])
275	
276	  const activeView = views.find((v) => v.id === activeViewId) ?? null
277	  const isInitialLoad = loading && clients.length === 0
278	
279	  return (
280	    <PageShell>
281	    <PullToRefresh
282	      onRefresh={async () => { router.refresh() }}
283	      className="flex flex-col gap-4"
284	    >
285	      {/* Header */}
286	      <div className="flex items-center justify-between">
287	        <div className="flex items-center gap-3">
288	          <div>
289	            <Typography variant="h1">Clients</Typography>
290	            <p className="text-sm text-muted-foreground mt-0.5">
291	              {totalCount !== null ? (
292	                <span className="tabular-nums">
293	                  {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
294	                </span>
295	              ) : clients.length > 0 ? (
296	                <span className="tabular-nums">{clients.length} client{clients.length !== 1 ? 's' : ''}</span>
297	              ) : null}
298	            </p>
299	          </div>
300	          {inactiveCount > 0 && (
301	            <span
302	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
303	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-xs font-medium px-2 py-0.5 select-none"
304	            >
305	              <span className="h-2 w-2 rounded-full bg-destructive shrink-0" aria-hidden="true" />
306	              {inactiveCount} inactive
307	            </span>
308	          )}
309	        </div>
310	        <Button onClick={handleNewClient}>
311	          <Plus className="mr-2 h-4 w-4" aria-hidden="true" />
312	          New client
313	        </Button>
314	      </div>
315	
316	      {/* Saved views switcher */}
317	      {views.length > 0 && (
318	        <SavedViewSwitcher
319	          views={views}
320	          activeViewId={activeViewId}
321	          onViewChange={handleViewChange}
322	          onCreateView={() => {
323	            setViewManagerMode('create')
324	            setEditingView(null)
325	            setViewManagerOpen(true)
326	          }}
327	          onEditView={(view) => {
328	            setViewManagerMode('edit')
329	            setEditingView(view)
330	            setViewManagerOpen(true)
331	          }}
332	          onDuplicateView={handleDuplicateView}
333	          onDeleteView={handleDeleteView}
334	          onSetDefault={handleSetDefaultView}
335	        />
336	      )}
337	
338	      {/* Unsaved changes banner */}
339	      {hasUnsavedChanges && activeView && !activeView.is_system && (
340	        <Alert className="py-2 border-warning/30 bg-warning/5">
341	          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
342	            <span className="text-warning dark:text-warning-foreground">
343	              Unsaved changes. Save view or discard?
344	            </span>
345	            <div className="flex gap-2 shrink-0">
346	              <Button
347	                size="sm"
348	                variant="outline"
349	                className="h-6 text-xs px-2"
350	                onClick={() => {
351	                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
352	                  setHasUnsavedChanges(false)
353	                }}
354	              >
355	                Discard
356	              </Button>
357	              <Button
358	                size="sm"
359	                className="h-6 text-xs px-2"
360	                onClick={() => {
361	                  setViewManagerMode('edit')
362	                  setEditingView(activeView)
363	                  setViewManagerOpen(true)
364	                }}
365	              >
366	                Save view
367	              </Button>
368	            </div>
369	          </AlertDescription>
370	        </Alert>
371	      )}
372	
373	      <ClientFilterBar
374	        filters={filters}
375	        onChange={handleFiltersChange}
376	        tagLibrary={tagLibrary}
377	      />
378	
379	      {selectedIds.length > 0 && (
380	        <BulkActionsBar
381	          selectedIds={selectedIds}
382	          tagLibrary={tagLibrary}
383	          onClearSelection={() => setSelectedIds([])}
384	          onArchived={() => void fetchClients(filters, 1)}
385	          onTagsApplied={() => void fetchClients(filters, 1)}
386	        />
387	      )}
388	
389	      <DataState
390	        data={clients}
391	        isLoading={isInitialLoad}
392	        isError={!!fetchError && clients.length === 0}
393	        error={fetchError}
394	        loadingSlot={<TableSkeleton rows={8} />}
395	        emptySlot={
396	          // Two distinct empty states per Clients Audit v1:
397	          //  1. DB empty (no clients ever created) — onboarding: + New client + CSV hint.
398	          //  2. Filters or saved view returned zero — help user reset.
399	          hasActiveFilters || (activeView && activeViewId) ? (
400	            activeView && activeViewId ? (
401	              <EmptyState
402	                icon={BookmarkX}
403	                title="No clients match these filters"
404	                description={`The filters in "${activeView.name}" returned no results.`}
405	                cta={{
406	                  label: 'Clear filters',
407	                  onClick: () => {
408	                    setFilters(DEFAULT_FILTERS)
409	                    setHasUnsavedChanges(false)
410	                  },
411	                }}
412	                ctaSecondary={{
413	                  label: 'Edit view filters',
414	                  onClick: () => {
415	                    setViewManagerMode('edit')
416	                    setEditingView(activeView)
417	                    setViewManagerOpen(true)
418	                  },
419	                }}
420	                variant="no-results"
421	              />
422	            ) : (
423	              <EmptyState
424	                icon={SearchX}
425	                title="No clients match these filters"
426	                description="Try different filters or clear all to see everyone."
427	                cta={{
428	                  label: 'Clear filters',
429	                  onClick: () => {
430	                    setFilters(DEFAULT_FILTERS)
431	                    setHasUnsavedChanges(false)
432	                  },
433	                }}
434	                variant="no-results"
435	              />
436	            )
437	          ) : (
438	            <EmptyState
439	              icon={Users}
440	              title="Add your first client"
441	              description="Start with a manual entry — CSV import is coming soon."
442	              cta={{ label: '+ New client', onClick: handleNewClient }}
443	              ctaSecondary={{
444	                label: 'Import from CSV',
445	                onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
446	              }}
447	              variant="first-time"
448	            />
449	          )
450	        }
451	        errorSlot={
452	          <PageError
453	            error={fetchError ?? new Error('Failed to load clients')}
454	            reset={() => void fetchClients(filters, 1)}
455	            variant="inline"
456	          />
457	        }
458	      >
459	        {(data) => (
460	          <ClientsTable
461	            clients={data}
462	            tagLibrary={tagLibrary}
463	            loading={loading && data.length === 0}
464	            selectedIds={selectedIds}
465	            onSelectionChange={setSelectedIds}
466	            onEdit={handleEditClient}
467	            onAddNote={(id) => setNoteClientId(id)}
468	          />
469	        )}
470	      </DataState>
471	
472	      {/* Load more */}
473	      {(hasMore || loading) && clients.length > 0 && (
474	        <div className="flex items-center justify-between py-4">
475	          <span className="text-sm text-muted-foreground tabular-nums">
476	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
477	          </span>
478	          {hasMore && (
479	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
480	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
481	              Load more
482	            </Button>
483	          )}
484	        </div>
485	      )}
486	
487	      <ClientDrawer
488	        open={drawerOpen}
489	        onOpenChange={(v) => {
490	          setDrawerOpen(v)
491	          if (!v) setEditingClient(null)
492	        }}
493	        client={editingClient}
494	        tagLibrary={tagLibrary}
495	        onSuccess={handleDrawerSuccess}
496	      />
497	
498	      {noteClientId && (
499	        <AddNoteModal
500	          open={Boolean(noteClientId)}
501	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
502	          clientId={noteClientId}
503	        />
504	      )}
505	
506	      <SavedViewManager
507	        open={viewManagerOpen}
508	        onOpenChange={setViewManagerOpen}
509	        mode={viewManagerMode}
510	        view={editingView}
511	        currentFilters={filters}
512	        onSaved={handleViewSaved}
513	      />
514	    </PullToRefresh>
515	    </PageShell>
516	  )
517	}
